===
<div class="flex gap-half">
  <%= link_to edit_card_path(card), class: "btn btn--circle-mobile borderless",
        data: {
          controller: "hotkey",
          action: "keydown.e@document->hotkey#click",
          bridge__overflow_menu_target: "item",
